draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // door
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.stroke();

  // lock
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // key
  ctx.beginPath();
  ctx.moveTo(W/2 - 70 + 30 * Math.sin(t), H/2 - 30);
  ctx.lineTo(W/2 - 70 + 30 * Math.sin(t), H/2 + 10);
  ctx.lineTo(W/2 - 50 + 30 * Math.sin(t), H/2 + 10);
  ctx.stroke();

  // key head
  ctx.beginPath();
  ctx.arc(W/2 - 70 + 30 * Math.sin(t), H/2 - 30, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // door opening
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50);
  ctx.arc(W/2, H/2 - 50, 50, -Math.PI/2, -Math.PI/2 + Math.sin(t) * Math.PI/2);
  ctx.lineTo(W/2 - 50, H/2 - 50);
  ctx.stroke();

  ctx.restore();
}
